"use strict";
const $=id=>document.getElementById(id);
const config=window.APP_CONFIG||{};
const hasConfig=typeof config.SUPABASE_URL==="string"&&typeof config.SUPABASE_ANON_KEY==="string"&&!config.SUPABASE_URL.includes("YOUR_PROJECT_ID")&&!config.SUPABASE_ANON_KEY.includes("YOUR_SUPABASE_ANON_KEY");
let db=null,authMode="login",toastTimer=null,progressTimer=null;
const state={session:null,user:null,profile:null,teamInfo:null,mangas:[],studioMangas:[],favoriteIds:new Set(),home:{latest:[],top10:[],completed:[]},membershipPlans:[],membership:null,membershipRequests:[],adminRequests:[],profileStats:{readingMangas:0,chapters:0},currentManga:null,currentChapters:[],managedManga:null,managedChapters:[],reader:{manga:null,chapter:null,chapters:[],pages:[]}};
const DEFAULT_MEMBERSHIP_PLANS=[{code:"month1",name:"1 сарын эрх",duration_months:1,price_mnt:6900,description:"Бүх нийтлэгдсэн манга болон бүлгийг 1 сар унших эрх.",active:true,sort_order:10},{code:"quarter",name:"Улирлын эрх",duration_months:3,price_mnt:26000,description:"Бүх нийтлэгдсэн манга болон бүлгийг 3 сар унших эрх.",active:true,sort_order:20},{code:"halfyear",name:"Хагас жилийн эрх",duration_months:6,price_mnt:38000,description:"Бүх нийтлэгдсэн манга болон бүлгийг 6 сар унших эрх.",active:true,sort_order:30},{code:"year",name:"Жилийн эрх",duration_months:12,price_mnt:81800,description:"Бүх нийтлэгдсэн манга болон бүлгийг 12 сар унших эрх.",active:true,sort_order:40}];
const escapeHTML=(v="")=>String(v).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");
function safeImage(url){if(!url)return"assets/logo.svg";try{const u=new URL(url,location.href);return["http:","https:"].includes(u.protocol)?u.href:"assets/logo.svg"}catch{return"assets/logo.svg"}}
function slugify(text){const base=String(text).normalize("NFKD").toLowerCase().replace(/[^a-z0-9\u0400-\u04ff]+/g,"-").replace(/^-+|-+$/g,"").slice(0,70);return`${base||"manga"}-${crypto.randomUUID().slice(0,8)}`}
function fileExtension(name){const ext=String(name).split(".").pop()?.toLowerCase();return ext&&/^[a-z0-9]+$/.test(ext)?ext:"webp"}
function setMessage(el,msg="",type=""){el.textContent=msg;el.className=`form-message${type?` ${type}`:""}`}
function showToast(msg,type=""){const t=$("toast");t.textContent=msg;t.className=`toast${type?` ${type}`:""}`;t.classList.remove("hidden");clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.add("hidden"),4200)}
function setButtonLoading(btn,on,text="Түр хүлээнэ үү..."){if(on){btn.dataset.originalText=btn.textContent;btn.textContent=text;btn.disabled=true}else{btn.textContent=btn.dataset.originalText||btn.textContent;btn.disabled=false}}
function formatDate(v){return v?new Intl.DateTimeFormat("mn-MN",{year:"numeric",month:"short",day:"numeric"}).format(new Date(v)):""}
function formatMoney(value){return new Intl.NumberFormat("mn-MN").format(Number(value||0))+"₮"}
function roleLabel(role){if(role==="admin")return"Админ";if(role==="translator")return"Орчуулагч";return"Уншигч"}
function hasReadingAccess(){return ["translator","admin"].includes(state.profile?.role)||Boolean(state.membership&&new Date(state.membership.expires_at)>new Date())}
function registerServiceWorker(){if("serviceWorker"in navigator&&location.protocol.startsWith("http"))addEventListener("load",()=>navigator.serviceWorker.register("./sw.js?v=9.0.0",{updateViaCache:"none"}).catch(()=>{}))}
function configureAuthMode(mode){authMode=mode;const reg=mode==="register";$("loginTab").classList.toggle("hidden",!reg);$("registerTab").classList.toggle("hidden",reg);$("forgotPasswordBtn").classList.toggle("hidden",reg);$("nameField").classList.toggle("hidden",!reg);$("authTitle").textContent=reg?"Шинэ бүртгэл":"Тавтай морил!";$("authSubtitle").textContent=reg?"Шинэ бүртгэл уншигчийн эрхээр үүснэ.":"Та бүртгэлтэй имэйл болон нууц үгээрээ нэвтэрнэ үү.";$("authModeHint").textContent=reg?"Орчуулагчийн эрхийг бүртгүүлсний дараа багийн тусгай кодоор нээнэ.":"Та бүртгүүлсний дараа манга унших боломжтой.";$("authSubmit").textContent=reg?"♙ Бүртгэл үүсгэх":"↪ Нэвтрэх";$("authSubmit").className=`auth-action ${reg?"auth-register":"auth-login"}`;$("password").autocomplete=reg?"new-password":"current-password";setMessage($("authMessage"))}
function updateInviteVisibility(){}
function getOAuthRedirectUrl(){const url=new URL("./",window.location.href);url.search="";url.hash="";return url.href}
async function handleOAuthLogin(provider,button){if(!db){setMessage($("authMessage"),"Эхлээд config.js файлд Supabase URL болон publishable key-г оруулна уу.","error");return}setMessage($("authMessage"));if(authMode==="register"){const role=document.querySelector('input[name="accountRole"]:checked')?.value||"reader",invite=$("inviteCode").value.trim();if(role==="translator"&&!invite){setMessage($("authMessage"),"Орчуулагчийн урилгын кодоо оруулсны дараа сошиал бүртгэлээр үргэлжлүүлнэ үү.","error");return}role==="translator"?localStorage.setItem("pendingTranslatorInvite",invite):localStorage.removeItem("pendingTranslatorInvite")}else localStorage.removeItem("pendingTranslatorInvite");setButtonLoading(button,true,"Холбож байна...");try{const options={redirectTo:getOAuthRedirectUrl()};if(provider==="azure")options.scopes="email";const{error}=await db.auth.signInWithOAuth({provider,options});if(error)throw error}catch(err){setMessage($("authMessage"),err.message||"Сошиал нэвтрэлт эхлүүлэх үед алдаа гарлаа.","error");setButtonLoading(button,false)}}
async function handleAuthSubmit(e){e.preventDefault();if(!db){setMessage($("authMessage"),"Эхлээд config.js файлд Supabase URL болон anon key-г оруулна уу.","error");return}const email=$("email").value.trim(),password=$("password").value,submit=$("authSubmit");setMessage($("authMessage"));if(!email||password.length<8){setMessage($("authMessage"),"Зөв имэйл болон доод тал нь 8 тэмдэгттэй нууц үг оруулна уу.","error");return}setButtonLoading(submit,true);try{if(authMode==="login"){const{error}=await db.auth.signInWithPassword({email,password});if(error)throw error;setMessage($("authMessage"),"Амжилттай нэвтэрлээ.","success");return}const displayName=$("displayName").value.trim();if(displayName.length<2)throw new Error("Нэрээ доод тал нь 2 тэмдэгтээр оруулна уу.");const{data,error}=await db.auth.signUp({email,password,options:{data:{display_name:displayName}}});if(error)throw error;if(data.session){setMessage($("authMessage"),"Бүртгэл амжилттай үүслээ. Орчуулагч бол Миний булан хэсэгт багийн кодоо оруулна уу.","success")}else setMessage($("authMessage"),"Баталгаажуулах холбоос таны имэйлд илгээгдлээ. Имэйлээ баталгаажуулаад нэвтэрнэ үү.","success")}catch(err){setMessage($("authMessage"),err.message||"Нэвтрэх үед алдаа гарлаа.","error")}finally{setButtonLoading(submit,false)}}
async function loadTeamInfo(){if(!state.user||!state.profile)return;const{data,error}=await db.rpc("get_my_translator_team");if(error){state.teamInfo=null;showToast(`Багийн мэдээлэл ачаалж чадсангүй: ${error.message}`,"error")}else state.teamInfo=data||null;renderTeamAccess()}
function renderTeamAccess(){const card=$("translatorTeamCard"),status=$("translatorTeamStatus"),meta=$("translatorTeamMeta"),form=$("translatorTeamJoinForm");if(!card||!status||!meta||!form||!state.profile)return;const translator=state.profile.role==="translator",admin=state.profile.role==="admin";card.classList.toggle("active",translator||admin);if(admin){status.textContent="Админ эрх идэвхтэй.";meta.textContent="Админ бүх орчуулагчийн хэсэгт хандах боломжтой.";form.classList.add("hidden");return}if(translator){const name=state.teamInfo?.name||"Орчуулагч баг",members=Number(state.teamInfo?.member_count||0),max=Number(state.teamInfo?.max_members||20);status.textContent=`${name} багийн орчуулагчийн эрх идэвхтэй.`;meta.textContent=`Багийн гишүүд: ${members}/${max}. Дахин код оруулах шаардлагагүй.`;form.classList.add("hidden")}else{status.textContent="Зөвхөн манайхаас багийн код авсан хэрэглэгч орчуулагчийн эрх нээнэ.";meta.textContent="Нэг кодыг 20 хүртэл тусдаа бүртгэл нэг удаа ашиглаж болно.";form.classList.remove("hidden")}}
async function joinTranslatorTeam(e){e.preventDefault();const code=$("translatorTeamCode").value.trim().toUpperCase(),msg=$("translatorTeamMessage"),btn=e.currentTarget.querySelector('button[type="submit"]');setMessage(msg);if(!code){setMessage(msg,"Багийн кодоо оруулна уу.","error");return}setButtonLoading(btn,true,"Шалгаж байна...");try{const{data,error}=await db.rpc("join_translator_team",{p_team_code:code});if(error)throw error;state.profile=await getProfile(state.user.id);state.teamInfo=data||null;$("translatorTeamCode").value="";$("studioNav").classList.remove("hidden");renderTeamAccess();renderProfileDashboard();await loadStudio();setMessage(msg,"Орчуулагчийн эрх амжилттай нээгдлээ.","success");showToast("Орчуулагчийн студи нээгдлээ.","success")}catch(err){setMessage(msg,err.message||"Код буруу эсвэл багийн 20 гишүүний лимит дүүрсэн байна.","error")}finally{setButtonLoading(btn,false)}}
async function getProfile(id,retries=3){for(let i=0;i<retries;i++){const{data,error}=await db.from("profiles").select("*").eq("id",id).maybeSingle();if(error)throw error;if(data)return data;await new Promise(r=>setTimeout(r,350))}throw new Error("Хэрэглэгчийн профайл үүсээгүй байна. supabase.sql файлыг ажиллуулсан эсэхээ шалгана уу.")}
async function handleSession(session){state.session=session;state.user=session?.user||null;if(!session){state.profile=null;state.teamInfo=null;state.membership=null;state.membershipRequests=[];state.adminRequests=[];document.body.classList.add("guest-mode");$("guestView").classList.remove("hidden");$("appView").classList.add("hidden");$("mainNav").classList.add("hidden");$("profileNav").classList.add("hidden");$("logoutBtn").classList.add("hidden");$("userBadge").classList.add("hidden");$("siteFooter").classList.add("hidden");return}try{document.body.classList.remove("guest-mode");state.profile=await getProfile(state.user.id);$("guestView").classList.add("hidden");$("appView").classList.remove("hidden");$("mainNav").classList.remove("hidden");$("profileNav").classList.remove("hidden");$("logoutBtn").classList.add("hidden");$("userBadge").classList.add("hidden");$("siteFooter").classList.remove("hidden");$("studioNav").classList.toggle("hidden",state.profile.role!=="translator");$("adminNav").classList.toggle("hidden",state.profile.role!=="admin");showView("library");await Promise.all([loadLibrary(),loadFavorites(),loadHomeSections(),loadMembershipData(),loadTeamInfo()]);await loadProfileDashboard();if(state.profile.role==="translator")await loadStudio()}catch(e){showToast(e.message||"Профайл ачааллах үед алдаа гарлаа.","error")}}
async function loadLibrary(){const{data,error}=await db.from("mangas").select("id,title,slug,description,cover_url,genres,status,series_status,is_featured,created_at,updated_at,translator_id").eq("status","published").order("updated_at",{ascending:false});if(error){showToast(`Номын сан ачаалж чадсангүй: ${error.message}`,"error");return}state.mangas=data||[];renderLibrary();renderFavorites();renderHomeSections()}
async function loadFavorites(){const{data,error}=await db.from("favorites").select("manga_id").eq("user_id",state.user.id);if(error){showToast(`Хадгалсан жагсаалт ачаалж чадсангүй: ${error.message}`,"error");return}state.favoriteIds=new Set((data||[]).map(x=>x.manga_id));renderLibrary();renderFavorites();renderHomeSections();renderProfileDashboard()}
function seriesStatusMeta(value){if(value==="completed")return{label:"Гарч дууссан",className:"completed"};if(value==="hiatus")return{label:"Түр завсарласан",className:"hiatus"};return{label:"Үргэлжилж буй",className:"ongoing"}}
function mangaCardTemplate(m,options={}){const genres=Array.isArray(m.genres)&&m.genres.length?m.genres.join(" · "):"Төрөл оруулаагүй",fav=state.favoriteIds.has(m.id),series=seriesStatusMeta(m.series_status),rank=Number(options.rank||0),hasStats=Object.hasOwn(m,"favorite_count")||Object.hasOwn(m,"latest_chapter"),latestChapter=m.latest_chapter!==null&&m.latest_chapter!==undefined?`Бүлэг ${m.latest_chapter}`:"Бүлэг ороогүй",favoriteCount=Number(m.favorite_count||0),stats=hasStats?`<div class="card-stats"><span>${escapeHTML(latestChapter)}</span><span>♥ ${favoriteCount}</span></div>`:"";return`<article class="manga-card ${rank?"ranked-card":""}"><div class="manga-cover-wrap" data-open-manga="${escapeHTML(m.id)}" tabindex="0" role="button">${rank?`<span class="rank-badge">#${rank}</span>`:""}<img class="manga-cover" src="${escapeHTML(safeImage(m.cover_url))}" alt="${escapeHTML(m.title)}" loading="lazy"><span class="series-badge ${series.className}">${series.label}</span><button class="favorite-mini ${fav?"active":""}" data-favorite="${escapeHTML(m.id)}" aria-label="${fav?"Хадгалснаас хасах":"Хадгалах"}">${fav?"♥":"♡"}</button></div><h3 title="${escapeHTML(m.title)}">${escapeHTML(m.title)}</h3><p>${escapeHTML(genres)}</p>${stats}</article>`}
async function loadHomeSections(){const{data,error}=await db.rpc("get_home_sections");if(error){showToast(`Нүүр хэсэг ачаалж чадсангүй: ${error.message}`,"error");state.home={latest:[],top10:[],completed:[]};renderHomeSections();return}state.home={latest:Array.isArray(data?.latest)?data.latest:[],top10:Array.isArray(data?.top10)?data.top10:[],completed:Array.isArray(data?.completed)?data.completed:[]};renderHomeSections()}
function renderHomeSections(){const latest=$("latestGrid"),top=$("top10Grid"),completed=$("completedGrid");if(!latest||!top||!completed)return;latest.innerHTML=state.home.latest.map(m=>mangaCardTemplate(m)).join("");top.innerHTML=state.home.top10.map((m,i)=>mangaCardTemplate(m,{rank:i+1})).join("");completed.innerHTML=state.home.completed.map(m=>mangaCardTemplate(m)).join("");$("latestEmpty").classList.toggle("hidden",state.home.latest.length!==0);$("top10Empty").classList.toggle("hidden",state.home.top10.length!==0);$("completedEmpty").classList.toggle("hidden",state.home.completed.length!==0);$("latestCount").textContent=state.home.latest.length?`${state.home.latest.length} бүтээл`:"";$("completedCount").textContent=state.home.completed.length?`${state.home.completed.length} бүтээл`:""}
function renderLibrary(){const q=$("searchInput").value.trim().toLowerCase(),items=state.mangas.filter(m=>`${m.title} ${(m.genres||[]).join(" ")} ${m.description||""}`.toLowerCase().includes(q));$("libraryGrid").innerHTML=items.map(m=>mangaCardTemplate(m)).join("");$("libraryEmpty").classList.toggle("hidden",items.length!==0);$("libraryCount").textContent=`${items.length} бүтээл`}
function renderFavorites(){const items=state.mangas.filter(m=>state.favoriteIds.has(m.id));$("favoritesGrid").innerHTML=items.map(mangaCardTemplate).join("");$("favoritesEmpty").classList.toggle("hidden",items.length!==0)}
async function toggleFavorite(id){const exists=state.favoriteIds.has(id);let error;if(exists)({error}=await db.from("favorites").delete().eq("user_id",state.user.id).eq("manga_id",id));else({error}=await db.from("favorites").insert({user_id:state.user.id,manga_id:id}));if(error){showToast(error.message,"error");return}exists?state.favoriteIds.delete(id):state.favoriteIds.add(id);renderLibrary();renderFavorites();renderHomeSections();loadHomeSections();if(state.currentManga?.id===id&&$("mangaDialog").open)renderMangaDetail()}
async function openManga(id){const manga=state.mangas.find(x=>x.id===id)||[...state.home.latest,...state.home.top10,...state.home.completed].find(x=>x.id===id);if(!manga)return;const{data,error}=await db.from("chapters").select("id,manga_id,chapter_number,title,published,created_at").eq("manga_id",id).eq("published",true).order("chapter_number");if(error){showToast(error.message,"error");return}state.currentManga=manga;state.currentChapters=data||[];renderMangaDetail();$("mangaDialog").showModal()}
function renderMangaDetail(){const m=state.currentManga;if(!m)return;const fav=state.favoriteIds.has(m.id),chs=state.currentChapters,tags=[`<span class="tag">${escapeHTML(seriesStatusMeta(m.series_status).label)}</span>`,...(m.genres||[]).map(g=>`<span class="tag">${escapeHTML(g)}</span>`)].join(""),rows=chs.length?chs.map(c=>`<button class="chapter-row" data-read-chapter="${escapeHTML(c.id)}"><span><strong>Бүлэг ${escapeHTML(c.chapter_number)}</strong><span>${escapeHTML(c.title||"Нэргүй бүлэг")}</span></span><span>${escapeHTML(formatDate(c.created_at))} →</span></button>`).join(""):`<div class="empty-state"><div class="empty-icon">◌</div><h3>Нийтлэгдсэн бүлэг алга</h3><p>Орчуулагч бүлгээ нийтэлсний дараа энд харагдана.</p></div>`;$("mangaDetail").innerHTML=`<div class="manga-detail-hero"><img class="detail-backdrop" src="${escapeHTML(safeImage(m.cover_url))}" alt=""><div class="detail-shade"></div><img class="detail-cover" src="${escapeHTML(safeImage(m.cover_url))}" alt="${escapeHTML(m.title)}"><div class="detail-copy"><span class="eyebrow">Монгол орчуулга</span><h2>${escapeHTML(m.title)}</h2><div class="tag-row">${tags||'<span class="tag">Манга</span>'}</div><p>${escapeHTML(m.description||"Тайлбар оруулаагүй.")}</p><div class="detail-actions"><button class="btn btn-primary" data-read-first="${escapeHTML(m.id)}" ${chs.length?"":"disabled"}>▶ Уншиж эхлэх</button><button class="btn btn-ghost" data-favorite="${escapeHTML(m.id)}">${fav?"♥ Хадгалсан":"♡ Хадгалах"}</button></div></div></div><div class="chapter-section"><h3>Бүлгүүд (${chs.length})</h3><div class="chapter-list">${rows}</div></div>`}
async function openReader(id,chapters=state.currentChapters,manga=state.currentManga){if(!hasReadingAccess()){if($("mangaDialog").open)$("mangaDialog").close();showView("membership");showToast("Бүлэг уншихын тулд идэвхтэй гишүүнчлэл шаардлагатай.","error");return}const chapter=chapters.find(x=>x.id===id);if(!chapter||!manga)return;if($("mangaDialog").open)$("mangaDialog").close();$("readerOverlay").classList.remove("hidden");document.body.style.overflow="hidden";$("readerMangaTitle").textContent=manga.title;$("readerChapterTitle").textContent=`Бүлэг ${chapter.chapter_number}${chapter.title?` — ${chapter.title}`:""}`;$("readerPages").innerHTML='<div class="reader-loading">Хуудсуудыг ачаалж байна...</div>';state.reader={manga,chapter,chapters,pages:[]};const idx=chapters.findIndex(x=>x.id===id);$("prevChapterBtn").disabled=idx<=0;$("nextChapterBtn").disabled=idx<0||idx>=chapters.length-1;const[{data:pages,error},{data:progress}]=await Promise.all([db.from("chapter_pages").select("id,image_url,page_order").eq("chapter_id",id).order("page_order"),db.from("reading_progress").select("page_index").eq("user_id",state.user.id).eq("chapter_id",id).maybeSingle()]);if(error){$("readerPages").innerHTML=`<div class="reader-loading">${escapeHTML(error.message)}</div>`;return}state.reader.pages=pages||[];if(!pages?.length){$("readerPages").innerHTML='<div class="reader-loading">Энэ бүлэгт хуудас оруулаагүй байна.</div>';return}$("readerPages").innerHTML=pages.map((p,i)=>`<img class="reader-page" data-page-index="${i}" src="${escapeHTML(safeImage(p.image_url))}" alt="${escapeHTML(manga.title)} ${i+1}-р хуудас">`).join("");const resume=Math.min(Number(progress?.page_index||0),pages.length-1);if(resume>0)setTimeout(()=>document.querySelector(`[data-page-index="${resume}"]`)?.scrollIntoView(),500);else $("readerOverlay").scrollTop=0;await saveReadingProgress(resume)}
async function saveReadingProgress(i=0){const id=state.reader.chapter?.id;if(!id||!state.user)return;await db.from("reading_progress").upsert({user_id:state.user.id,chapter_id:id,page_index:Math.max(0,i),updated_at:new Date().toISOString()},{onConflict:"user_id,chapter_id"})}
function trackReaderProgress(){clearTimeout(progressTimer);progressTimer=setTimeout(()=>{const imgs=[...document.querySelectorAll(".reader-page")];if(!imgs.length)return;let best=0,dist=Infinity;imgs.forEach((im,i)=>{const d=Math.abs(im.getBoundingClientRect().top-90);if(d<dist){dist=d;best=i}});saveReadingProgress(best)},500)}
function closeReader(){trackReaderProgress();$("readerOverlay").classList.add("hidden");document.body.style.overflow="";state.reader={manga:null,chapter:null,chapters:[],pages:[]}}
function navigateReader(dir){const chs=state.reader.chapters,i=chs.findIndex(x=>x.id===state.reader.chapter?.id),next=chs[i+dir];if(next)openReader(next.id,chs,state.reader.manga)}
async function loadMembershipData(){if(!state.user)return;const[plansRes,membershipRes,requestsRes]=await Promise.all([db.from("membership_plans").select("*").eq("active",true).order("sort_order"),db.from("memberships").select("*").eq("user_id",state.user.id).maybeSingle(),db.from("membership_requests").select("*").eq("user_id",state.user.id).order("created_at",{ascending:false}).limit(20)]);if(plansRes.error)showToast(`Багц ачааллах алдаа: ${plansRes.error.message}`,"error");if(membershipRes.error)showToast(membershipRes.error.message,"error");if(requestsRes.error)showToast(requestsRes.error.message,"error");state.membershipPlans=plansRes.data?.length?plansRes.data:DEFAULT_MEMBERSHIP_PLANS;state.membership=membershipRes.data||null;state.membershipRequests=requestsRes.data||[];renderMembership();renderProfileDashboard()}
function membershipStatusMeta(status){if(status==="approved")return{label:"Баталгаажсан",className:"approved"};if(status==="rejected")return{label:"Татгалзсан",className:"rejected"};return{label:"Шалгаж байна",className:"pending"}}
function renderMembership(){const status=$("membershipStatus"),plans=$("membershipPlans"),select=$("membershipPlanSelect"),requests=$("membershipRequests");if(!status||!plans||!select||!requests)return;const active=Boolean(state.membership&&new Date(state.membership.expires_at)>new Date()),pending=state.membershipRequests.some(r=>r.status==="pending");if(["translator","admin"].includes(state.profile?.role)){status.className="membership-status-card active";status.innerHTML=`<span class="eyebrow">Тусгай эрх</span><h3>${roleLabel(state.profile.role)} эрх идэвхтэй</h3><p>Таны эрхээр бүх нийтлэгдсэн бүлгийг унших боломжтой.</p>`}else if(active){status.className="membership-status-card active";status.innerHTML=`<span class="eyebrow">Идэвхтэй гишүүн</span><h3>Унших эрх нээлттэй</h3><p>Гишүүнчлэл <strong>${escapeHTML(formatDate(state.membership.expires_at))}</strong> хүртэл хүчинтэй.</p>`}else if(pending){status.className="membership-status-card pending";status.innerHTML=`<span class="eyebrow">Хүлээгдэж байна</span><h3>Төлбөрийн хүсэлтийг шалгаж байна</h3><p>Админ банкны гүйлгээ болон баримтыг баталгаажуулсны дараа эрх автоматаар нээгдэнэ.</p>`}else{status.className="membership-status-card";status.innerHTML=`<span class="eyebrow">Эрх идэвхгүй</span><h3>Бүлэг уншихын тулд багц сонгоно уу</h3><p>Манганы жагсаалт харах боломжтой. Бүлгийн зургууд зөвхөн идэвхтэй гишүүнчлэлтэй үед нээгдэнэ.</p>`}plans.innerHTML=state.membershipPlans.map(p=>`<article class="membership-plan" data-plan-card="${escapeHTML(p.code)}"><span class="eyebrow">${escapeHTML(p.duration_months)} сар</span><h3>${escapeHTML(p.name)}</h3><div class="membership-plan-price">${escapeHTML(formatMoney(p.price_mnt))} <small>/ нийт</small></div><p>${escapeHTML(p.description||`${p.duration_months} сарын унших эрх`)}</p><button class="btn btn-primary" type="button" data-select-plan="${escapeHTML(p.code)}">Сонгох</button></article>`).join("");select.innerHTML='<option value="">Багц сонгоно уу</option>'+state.membershipPlans.map(p=>`<option value="${escapeHTML(p.code)}">${escapeHTML(p.name)} — ${escapeHTML(formatMoney(p.price_mnt))}</option>`).join("");requests.innerHTML=state.membershipRequests.length?state.membershipRequests.map(r=>{const plan=state.membershipPlans.find(p=>p.code===r.plan_code),meta=membershipStatusMeta(r.status);return`<article class="request-item"><div><h3>${escapeHTML(plan?.name||r.plan_code)} · ${escapeHTML(formatMoney(r.amount_mnt))}</h3><div class="request-meta"><span>${escapeHTML(formatDate(r.created_at))}</span><span>${escapeHTML(r.transfer_reference)}</span>${r.admin_note?`<span>Тайлбар: ${escapeHTML(r.admin_note)}</span>`:""}</div></div><span class="status-pill ${meta.className}">${meta.label}</span></article>`}).join(""):'<div class="section-empty">Одоогоор төлбөрийн хүсэлт илгээгээгүй байна.</div>';const today=new Date().toISOString().slice(0,10);if(!$("membershipTransferDate").value)$("membershipTransferDate").value=today}
function selectMembershipPlan(code){const plan=state.membershipPlans.find(p=>p.code===code);if(!plan)return;$("membershipPlanSelect").value=code;document.querySelectorAll("[data-plan-card]").forEach(el=>el.classList.toggle("selected",el.dataset.planCard===code));$("transferMeaningExample").textContent=`${state.profile?.display_name||"username"} · ${state.user?.email||"email"} · ${plan.duration_months} сар`;$("membershipReference").value=`${state.profile?.display_name||""} · ${state.user?.email||""} · ${plan.duration_months} сар`;$("membershipRequestForm").scrollIntoView({behavior:"smooth",block:"center"})}
async function submitMembershipRequest(e){e.preventDefault();const form=e.currentTarget,btn=form.querySelector('button[type="submit"]'),msg=$("membershipMessage"),planCode=$("membershipPlanSelect").value,sender=$("membershipSenderName").value.trim(),reference=$("membershipReference").value.trim(),date=$("membershipTransferDate").value,file=$("membershipReceipt").files[0];setMessage(msg);if(!planCode||!sender||!reference||!date||!file){setMessage(msg,"Бүх талбарыг бөглөж, төлбөрийн баримтаа сонгоно уу.","error");return}const allowed=["image/jpeg","image/png","image/webp","application/pdf"];if(!allowed.includes(file.type)){setMessage(msg,"Баримт JPEG, PNG, WEBP эсвэл PDF байна.","error");return}if(file.size>10*1024*1024){setMessage(msg,"Баримтын хэмжээ 10MB-аас бага байна.","error");return}setButtonLoading(btn,true,"Илгээж байна...");const ext=fileExtension(file.name),path=`${state.user.id}/${crypto.randomUUID()}.${ext}`;try{const{error:uploadError}=await db.storage.from("membership-receipts").upload(path,file,{upsert:false,contentType:file.type});if(uploadError)throw uploadError;const{error}=await db.rpc("submit_membership_request",{p_plan_code:planCode,p_sender_name:sender,p_transfer_reference:reference,p_transfer_date:date,p_receipt_path:path});if(error){await db.storage.from("membership-receipts").remove([path]);throw error}form.reset();setMessage(msg,"Хүсэлт амжилттай илгээгдлээ. Админ баталгаажуулахыг хүлээнэ үү.","success");await loadMembershipData()}catch(err){setMessage(msg,err.message||"Хүсэлт илгээх үед алдаа гарлаа.","error")}finally{setButtonLoading(btn,false)}}
async function loadAdminRequests(){if(state.profile?.role!=="admin")return;const{data,error}=await db.from("membership_requests").select("*").order("created_at",{ascending:false}).limit(100);if(error){showToast(error.message,"error");return}const ids=[...new Set((data||[]).map(r=>r.user_id))];let profiles=[];if(ids.length){const res=await db.from("profiles").select("id,display_name").in("id",ids);if(res.error)showToast(res.error.message,"error");else profiles=res.data||[]}const profileMap=new Map(profiles.map(p=>[p.id,p]));state.adminRequests=(data||[]).map(r=>({...r,display_name:profileMap.get(r.user_id)?.display_name||"Хэрэглэгч"}));renderAdminRequests()}
function renderAdminRequests(){const root=$("adminRequests");if(!root)return;root.innerHTML=state.adminRequests.length?state.adminRequests.map(r=>{const plan=state.membershipPlans.find(p=>p.code===r.plan_code),meta=membershipStatusMeta(r.status);return`<article class="admin-request"><div class="admin-request-details"><h3>${escapeHTML(r.display_name)} · ${escapeHTML(plan?.name||r.plan_code)}</h3><p>${escapeHTML(formatMoney(r.amount_mnt))} · ${escapeHTML(r.sender_name)} · ${escapeHTML(r.transfer_date)}</p><p>Гүйлгээний утга: ${escapeHTML(r.transfer_reference)}</p><div class="request-meta"><span>${escapeHTML(formatDate(r.created_at))}</span><span class="status-pill ${meta.className}">${meta.label}</span>${r.admin_note?`<span>Админы тайлбар: ${escapeHTML(r.admin_note)}</span>`:""}</div></div><div class="admin-request-actions"><button class="btn btn-ghost" type="button" data-open-receipt="${escapeHTML(r.receipt_path)}">Баримт</button>${r.status==="pending"?`<button class="btn btn-primary" type="button" data-review-request="${escapeHTML(r.id)}" data-review-action="approve">Зөвшөөрөх</button><button class="btn btn-danger" type="button" data-review-request="${escapeHTML(r.id)}" data-review-action="reject">Татгалзах</button>`:""}</div></article>`}).join(""):'<div class="empty-state"><div class="empty-icon">✓</div><h3>Хүсэлт алга</h3><p>Шинэ төлбөрийн хүсэлт ирэхэд энд харагдана.</p></div>'}
async function openMembershipReceipt(path){const{data,error}=await db.storage.from("membership-receipts").createSignedUrl(path,120);if(error){showToast(error.message,"error");return}window.open(data.signedUrl,"_blank","noopener,noreferrer")}
async function reviewMembershipRequest(id,approve){const verb=approve?"зөвшөөрөх":"татгалзах";if(!confirm(`Энэ хүсэлтийг ${verb} үү?`))return;const note=prompt("Админы тайлбар (заавал биш):","")||"";const{error}=await db.rpc("review_membership_request",{p_request_id:id,p_approve:approve,p_admin_note:note});if(error){showToast(error.message,"error");return}showToast(approve?"Гишүүнчлэлийн эрх нээгдлээ.":"Хүсэлтэд татгалзлаа.","success");await loadAdminRequests()}
async function copyText(value){try{await navigator.clipboard.writeText(value);showToast("Хуулагдлаа.","success")}catch{showToast("Хуулах боломжгүй байна.","error")}}
async function loadStudio(){let query=db.from("mangas").select("id,title,slug,description,cover_url,cover_path,genres,status,series_status,is_featured,created_at,updated_at,translator_id,team_id").order("updated_at",{ascending:false});query=state.profile?.translator_team_id?query.eq("team_id",state.profile.translator_team_id):query.eq("translator_id",state.user.id);const{data,error}=await query;if(error){showToast(`Студи ачаалж чадсангүй: ${error.message}`,"error");return}state.studioMangas=data||[];renderStudio()}
function renderStudio(){$("studioGrid").innerHTML=state.studioMangas.map(m=>{const tags=(m.genres||[]).map(g=>`<span class="tag">${escapeHTML(g)}</span>`).join("");return`<article class="studio-item"><img src="${escapeHTML(safeImage(m.cover_url))}" alt="${escapeHTML(m.title)}"><div class="studio-meta"><h3>${escapeHTML(m.title)}</h3><p>${m.status==="published"?"Нийтлэгдсэн":"Ноорог"} · ${seriesStatusMeta(m.series_status).label} · ${escapeHTML(formatDate(m.updated_at||m.created_at))}</p><div class="tag-row">${tags||'<span class="tag">Төрөлгүй</span>'}</div></div><div class="studio-actions"><button class="btn btn-ghost" data-manage-manga="${escapeHTML(m.id)}">Удирдах</button><button class="btn btn-ghost" data-toggle-publish="${escapeHTML(m.id)}">${m.status==="published"?"Нуух":"Нийтлэх"}</button><button class="btn btn-danger" data-delete-manga="${escapeHTML(m.id)}">Устгах</button></div></article>`}).join("");$("studioEmpty").classList.toggle("hidden",state.studioMangas.length!==0)}
async function uploadImage(path,file){if(!file.type.startsWith("image/"))throw new Error(`${file.name}: зөвхөн зураг оруулна.`);if(file.size>12*1024*1024)throw new Error(`${file.name}: 12MB-аас их байна.`);const{error}=await db.storage.from("manga-pages").upload(path,file,{cacheControl:"31536000",upsert:false,contentType:file.type});if(error)throw error;return db.storage.from("manga-pages").getPublicUrl(path).data.publicUrl}
async function createManga(e){e.preventDefault();const form=e.currentTarget,submit=form.querySelector('button[type="submit"]'),msg=$("createMangaMessage"),file=$("mangaCover").files[0],title=$("mangaTitle").value.trim(),description=$("mangaDescription").value.trim(),genres=$("mangaGenres").value.split(",").map(x=>x.trim()).filter(Boolean).slice(0,12),status=$("mangaPublished").checked?"published":"draft",seriesStatus=$("mangaSeriesStatus").value,isFeatured=$("mangaFeatured").checked;if(!file){setMessage(msg,"Нүүр зураг сонгоно уу.","error");return}setButtonLoading(submit,true,"Үүсгэж байна...");let id=null,path=null;try{const{data:m,error}=await db.from("mangas").insert({translator_id:state.user.id,team_id:state.profile?.translator_team_id||null,title,slug:slugify(title),description,genres,status,series_status:seriesStatus,is_featured:isFeatured}).select().single();if(error)throw error;id=m.id;path=`${state.user.id}/${m.id}/cover-${crypto.randomUUID()}.${fileExtension(file.name)}`;const url=await uploadImage(path,file);const{error:upErr}=await db.from("mangas").update({cover_url:url,cover_path:path}).eq("id",m.id);if(upErr)throw upErr;form.reset();$("createMangaDialog").close();showToast("Манга амжилттай үүслээ.","success");await Promise.all([loadStudio(),loadLibrary(),loadHomeSections()])}catch(err){if(path)await db.storage.from("manga-pages").remove([path]);if(id)await db.from("mangas").delete().eq("id",id);setMessage(msg,err.message||"Манга үүсгэх үед алдаа гарлаа.","error")}finally{setButtonLoading(submit,false)}}
async function toggleMangaPublish(id){const m=state.studioMangas.find(x=>x.id===id);if(!m)return;const status=m.status==="published"?"draft":"published",{error}=await db.from("mangas").update({status,updated_at:new Date().toISOString()}).eq("id",id);if(error){showToast(error.message,"error");return}showToast(status==="published"?"Манга нийтлэгдлээ.":"Манга номын сангаас нуугдлаа.","success");await Promise.all([loadStudio(),loadLibrary(),loadHomeSections()])}
async function deleteManga(id){const m=state.studioMangas.find(x=>x.id===id);if(!m||!confirm(`“${m.title}” манга болон бүх бүлгийг бүр мөсөн устгах уу?`))return;try{const{data:chs,error}=await db.from("chapters").select("id").eq("manga_id",id);if(error)throw error;const ids=(chs||[]).map(x=>x.id);let paths=m.cover_path?[m.cover_path]:[];if(ids.length){const{data:pages,error:pErr}=await db.from("chapter_pages").select("storage_path").in("chapter_id",ids);if(pErr)throw pErr;paths=paths.concat((pages||[]).map(x=>x.storage_path).filter(Boolean))}if(paths.length)await db.storage.from("manga-pages").remove(paths);const{error:dErr}=await db.from("mangas").delete().eq("id",id);if(dErr)throw dErr;showToast("Манга устгагдлаа.","success");await Promise.all([loadStudio(),loadLibrary(),loadHomeSections()])}catch(err){showToast(err.message||"Устгах үед алдаа гарлаа.","error")}}
async function openManageManga(id){const m=state.studioMangas.find(x=>x.id===id);if(!m)return;const{data,error}=await db.from("chapters").select("*").eq("manga_id",id).order("chapter_number");if(error){showToast(error.message,"error");return}state.managedManga=m;state.managedChapters=data||[];renderManageManga();$("manageMangaDialog").showModal()}
function renderManageManga(){const m=state.managedManga;if(!m)return;const rows=state.managedChapters.map(c=>`<div class="manage-chapter-row"><div><strong>Бүлэг ${escapeHTML(c.chapter_number)} — ${escapeHTML(c.title||"Нэргүй")}</strong><small>${c.published?"Нийтлэгдсэн":"Ноорог"} · ${escapeHTML(formatDate(c.created_at))}</small></div><div class="mini-actions"><button class="mini-btn" data-toggle-chapter="${escapeHTML(c.id)}">${c.published?"◉":"○"}</button><button class="mini-btn" data-delete-chapter="${escapeHTML(c.id)}">⌫</button></div></div>`).join("");$("manageMangaContent").innerHTML=`<div class="manage-header"><span class="eyebrow">Бүтээл удирдах</span><h2>${escapeHTML(m.title)}</h2><p>Манганы мэдээллийг засах, шинэ бүлэг нэмэх, нийтлэх төлвийг удирдана.</p></div><div class="manage-body"><div class="manage-card"><h3>Манганы мэдээлэл</h3><form id="editMangaForm" class="stack-form"><label class="field"><span>Нэр</span><input id="editMangaTitle" value="${escapeHTML(m.title)}" required maxlength="120"></label><label class="field"><span>Тайлбар</span><textarea id="editMangaDescription" required maxlength="1200" rows="5">${escapeHTML(m.description||"")}</textarea></label><label class="field"><span>Төрөл</span><input id="editMangaGenres" value="${escapeHTML((m.genres||[]).join(", "))}" maxlength="180"></label><label class="field"><span>Цувралын төлөв</span><select id="editMangaSeriesStatus"><option value="ongoing" ${m.series_status==="ongoing"?"selected":""}>Үргэлжилж буй</option><option value="completed" ${m.series_status==="completed"?"selected":""}>Гарч дууссан</option><option value="hiatus" ${m.series_status==="hiatus"?"selected":""}>Түр завсарласан</option></select></label><label class="field"><span>Шинэ нүүр зураг (заавал биш)</span><input id="editMangaCover" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="toggle-row"><input id="editMangaFeatured" type="checkbox" ${m.is_featured?"checked":""}> Онцлох хэсэгт харуулах</label><label class="toggle-row"><input id="editMangaPublished" type="checkbox" ${m.status==="published"?"checked":""}> Нийтлэгдсэн</label><button class="btn btn-primary btn-block" type="submit">Хадгалах</button><p id="editMangaMessage" class="form-message"></p></form></div><div><div class="manage-card"><h3>Шинэ бүлэг</h3><form id="createChapterForm" class="stack-form"><label class="field"><span>Бүлгийн дугаар</span><input id="chapterNumber" type="number" min="0" step="0.1" required placeholder="1"></label><label class="field"><span>Бүлгийн нэр</span><input id="chapterTitle" maxlength="160" placeholder="Эхлэл"></label><label class="field"><span>Хуудасны зургууд</span><input id="chapterPages" type="file" accept="image/jpeg,image/png,image/webp" multiple required></label><label class="toggle-row"><input id="chapterPublished" type="checkbox"> Шууд нийтлэх</label><button class="btn btn-primary btn-block" type="submit">Бүлэг оруулах</button><p id="createChapterMessage" class="form-message"></p></form></div><div class="manage-card" style="margin-top:18px"><h3>Бүлгүүд (${state.managedChapters.length})</h3><div class="manage-chapters">${rows||'<p class="form-message">Бүлэг оруулаагүй байна.</p>'}</div></div></div></div>`;$("editMangaForm").addEventListener("submit",editManagedManga);$("createChapterForm").addEventListener("submit",createChapter)}
async function editManagedManga(e){e.preventDefault();const btn=e.currentTarget.querySelector('button[type="submit"]'),msg=$("editMangaMessage"),m=state.managedManga,file=$("editMangaCover").files[0];let newPath=null;setButtonLoading(btn,true,"Хадгалж байна...");try{const updates={title:$("editMangaTitle").value.trim(),description:$("editMangaDescription").value.trim(),genres:$("editMangaGenres").value.split(",").map(x=>x.trim()).filter(Boolean).slice(0,12),series_status:$("editMangaSeriesStatus").value,is_featured:$("editMangaFeatured").checked,status:$("editMangaPublished").checked?"published":"draft",updated_at:new Date().toISOString()};if(file){newPath=`${state.user.id}/${m.id}/cover-${crypto.randomUUID()}.${fileExtension(file.name)}`;updates.cover_url=await uploadImage(newPath,file);updates.cover_path=newPath}const{data,error}=await db.from("mangas").update(updates).eq("id",m.id).select().single();if(error)throw error;if(file&&m.cover_path)await db.storage.from("manga-pages").remove([m.cover_path]);state.managedManga=data;setMessage(msg,"Мэдээлэл хадгалагдлаа.","success");await Promise.all([loadStudio(),loadLibrary(),loadHomeSections()]);setTimeout(renderManageManga,400)}catch(err){if(newPath)await db.storage.from("manga-pages").remove([newPath]);setMessage(msg,err.message||"Хадгалах үед алдаа гарлаа.","error")}finally{setButtonLoading(btn,false)}}
async function createChapter(e){e.preventDefault();const form=e.currentTarget,btn=form.querySelector('button[type="submit"]'),msg=$("createChapterMessage"),files=[...$("chapterPages").files],m=state.managedManga;if(!files.length){setMessage(msg,"Доод тал нь нэг хуудасны зураг сонгоно уу.","error");return}if(files.length>250){setMessage(msg,"Нэг бүлэгт хамгийн ихдээ 250 зураг оруулна.","error");return}setButtonLoading(btn,true,"Бүлэг оруулж байна...");let chapterId=null;const paths=[];try{const{data:c,error}=await db.from("chapters").insert({manga_id:m.id,chapter_number:Number($("chapterNumber").value),title:$("chapterTitle").value.trim(),published:$("chapterPublished").checked}).select().single();if(error)throw error;chapterId=c.id;const rows=[];for(let i=0;i<files.length;i++){const f=files[i];setMessage(msg,`${i+1}/${files.length} хуудсыг байршуулж байна...`);const path=`${state.user.id}/${m.id}/${c.id}/${String(i+1).padStart(4,"0")}-${crypto.randomUUID()}.${fileExtension(f.name)}`,url=await uploadImage(path,f);paths.push(path);rows.push({chapter_id:c.id,image_url:url,storage_path:path,page_order:i+1})}const{error:pErr}=await db.from("chapter_pages").insert(rows);if(pErr)throw pErr;form.reset();const{data}=await db.from("chapters").select("*").eq("manga_id",m.id).order("chapter_number");state.managedChapters=data||[];renderManageManga();showToast("Бүлэг амжилттай орлоо.","success");await Promise.all([loadLibrary(),loadHomeSections()])}catch(err){if(paths.length)await db.storage.from("manga-pages").remove(paths);if(chapterId)await db.from("chapters").delete().eq("id",chapterId);setMessage(msg,err.message||"Бүлэг оруулах үед алдаа гарлаа.","error")}finally{setButtonLoading(btn,false)}}
async function toggleChapter(id){const c=state.managedChapters.find(x=>x.id===id);if(!c)return;const{error}=await db.from("chapters").update({published:!c.published}).eq("id",id);if(error){showToast(error.message,"error");return}c.published=!c.published;renderManageManga();showToast(c.published?"Бүлэг нийтлэгдлээ.":"Бүлэг нуугдлаа.","success");await Promise.all([loadLibrary(),loadHomeSections()])}
async function deleteChapter(id){const c=state.managedChapters.find(x=>x.id===id);if(!c||!confirm(`Бүлэг ${c.chapter_number}-г бүх хуудастай нь устгах уу?`))return;try{const{data:pages,error}=await db.from("chapter_pages").select("storage_path").eq("chapter_id",id);if(error)throw error;const paths=(pages||[]).map(x=>x.storage_path).filter(Boolean);if(paths.length)await db.storage.from("manga-pages").remove(paths);const{error:dErr}=await db.from("chapters").delete().eq("id",id);if(dErr)throw dErr;state.managedChapters=state.managedChapters.filter(x=>x.id!==id);renderManageManga();showToast("Бүлэг устгагдлаа.","success")}catch(err){showToast(err.message||"Устгах үед алдаа гарлаа.","error")}}

async function loadProfileDashboard(){if(!state.user||!state.profile)return;let rows=[];const expanded=await db.from("reading_progress").select("chapter_id,updated_at,chapters(manga_id)").eq("user_id",state.user.id).order("updated_at",{ascending:false});if(expanded.error){const fallback=await db.from("reading_progress").select("chapter_id,updated_at").eq("user_id",state.user.id).order("updated_at",{ascending:false});if(!fallback.error)rows=fallback.data||[]}else rows=expanded.data||[];const mangaIds=new Set(rows.map(r=>r.chapters?.manga_id).filter(Boolean));state.profileStats={readingMangas:mangaIds.size||rows.length,chapters:rows.length};renderProfileDashboard()}
function renderProfileDashboard(){if(!state.profile||!state.user)return;renderTeamAccess();const display=state.profile.display_name||state.user.email?.split("@")[0]||"Хэрэглэгч",initial=display.trim().charAt(0).toUpperCase()||"U";if($("profileAvatar"))$("profileAvatar").textContent=initial;if($("profileLargeAvatar"))$("profileLargeAvatar").textContent=initial;if($("profileDisplayName"))$("profileDisplayName").textContent=display;if($("profileEmail"))$("profileEmail").textContent=state.user.email||"";if($("profileRole"))$("profileRole").textContent=roleLabel(state.profile.role);if($("profileReadingCount"))$("profileReadingCount").textContent=String(state.profileStats.readingMangas||0);if($("profileFavoriteCount"))$("profileFavoriteCount").textContent=String(state.favoriteIds.size||0);if($("profileChapterCount"))$("profileChapterCount").textContent=String(state.profileStats.chapters||0);const active=Boolean(state.membership&&new Date(state.membership.expires_at)>new Date()),pending=state.membershipRequests.some(r=>r.status==="pending"),text=$("profileMembershipText"),sub=$("profileMembershipSubtext");if(!text||!sub)return;if(["translator","admin"].includes(state.profile.role)){text.textContent=`${roleLabel(state.profile.role)} эрх идэвхтэй`;sub.textContent="Таны тусгай эрхээр бүх нийтлэгдсэн бүлгийг унших боломжтой."}else if(active){text.textContent=`Plus+ эрх ${formatDate(state.membership.expires_at)} хүртэл идэвхтэй`;sub.textContent="Та бүх нийтлэгдсэн манганы бүлгийг унших боломжтой."}else if(pending){text.textContent="Төлбөрийн хүсэлтийг шалгаж байна";sub.textContent="Админ баталгаажуулсны дараа Plus+ эрх автоматаар нээгдэнэ."}else{text.textContent="Танд одоогоор Plus+ эрх байхгүй.";sub.textContent="Plus+ эрх авснаар бүх бүлгийг унших боломжтой."}}
async function requestPasswordReset(){const email=$("email").value.trim();setMessage($("authMessage"));if(!email){setMessage($("authMessage"),"Нууц үг сэргээх имэйл хаягаа оруулна уу.","error");$("email").focus();return}if(!db){setMessage($("authMessage"),"Supabase холболт бэлэн биш байна.","error");return}const btn=$("forgotPasswordBtn");setButtonLoading(btn,true,"Илгээж байна...");try{const redirectTo=`${location.origin}${location.pathname}`;const{error}=await db.auth.resetPasswordForEmail(email,{redirectTo});if(error)throw error;setMessage($("authMessage"),"Нууц үг шинэчлэх холбоос таны имэйл рүү илгээгдлээ.","success")}catch(err){setMessage($("authMessage"),err.message||"Сэргээх холбоос илгээж чадсангүй.","error")}finally{setButtonLoading(btn,false)}}
async function updateRecoveredPassword(e){e.preventDefault();const password=$("newPassword").value,btn=e.currentTarget.querySelector('button[type="submit"]'),msg=$("resetPasswordMessage");setMessage(msg);if(password.length<8){setMessage(msg,"Нууц үг доод тал нь 8 тэмдэгт байна.","error");return}setButtonLoading(btn,true,"Хадгалж байна...");try{const{error}=await db.auth.updateUser({password});if(error)throw error;setMessage(msg,"Нууц үг амжилттай шинэчлэгдлээ.","success");setTimeout(()=>$("resetPasswordDialog").close(),900)}catch(err){setMessage(msg,err.message||"Нууц үг шинэчилж чадсангүй.","error")}finally{setButtonLoading(btn,false)}}

function showView(view){const allowed=["library","favorites","membership","studio","admin","profile"];if(!allowed.includes(view)||view==="studio"&&state.profile?.role!=="translator"||view==="admin"&&state.profile?.role!=="admin")return;allowed.forEach(x=>$(x+"View")?.classList.toggle("hidden",x!==view));document.querySelectorAll(".nav-link[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===view));window.scrollTo({top:0,behavior:"smooth"});if(view==="favorites")renderFavorites();if(view==="membership")loadMembershipData();if(view==="studio")loadStudio();if(view==="admin")loadAdminRequests();if(view==="profile"){loadProfileDashboard();loadTeamInfo()}}
function handleDocumentClick(e){const target=e.target.closest("[data-view-target]");if(target){e.preventDefault();showView(target.dataset.viewTarget);return}const close=e.target.closest("[data-close-dialog]");if(close){$(close.dataset.closeDialog)?.close();return}const copy=e.target.closest("[data-copy-text]");if(copy){copyText(copy.dataset.copyText);return}const plan=e.target.closest("[data-select-plan]");if(plan){selectMembershipPlan(plan.dataset.selectPlan);return}const refreshMember=e.target.closest("[data-refresh-membership]");if(refreshMember){loadMembershipData();return}const refreshAdmin=e.target.closest("[data-refresh-admin]");if(refreshAdmin){loadAdminRequests();return}const receipt=e.target.closest("[data-open-receipt]");if(receipt){openMembershipReceipt(receipt.dataset.openReceipt);return}const review=e.target.closest("[data-review-request]");if(review){reviewMembershipRequest(review.dataset.reviewRequest,review.dataset.reviewAction==="approve");return}const fav=e.target.closest("[data-favorite]");if(fav){e.stopPropagation();toggleFavorite(fav.dataset.favorite);return}const manga=e.target.closest("[data-open-manga]");if(manga){openManga(manga.dataset.openManga);return}const read=e.target.closest("[data-read-chapter]");if(read){openReader(read.dataset.readChapter);return}const first=e.target.closest("[data-read-first]");if(first&&state.currentChapters[0]){openReader(state.currentChapters[0].id);return}const manage=e.target.closest("[data-manage-manga]");if(manage){openManageManga(manage.dataset.manageManga);return}const pub=e.target.closest("[data-toggle-publish]");if(pub){toggleMangaPublish(pub.dataset.togglePublish);return}const del=e.target.closest("[data-delete-manga]");if(del){deleteManga(del.dataset.deleteManga);return}const tc=e.target.closest("[data-toggle-chapter]");if(tc){toggleChapter(tc.dataset.toggleChapter);return}const dc=e.target.closest("[data-delete-chapter]");if(dc)deleteChapter(dc.dataset.deleteChapter)}
function bindEvents(){$("loginTab").addEventListener("click",()=>configureAuthMode("login"));$("registerTab").addEventListener("click",()=>configureAuthMode("register"));$("forgotPasswordBtn").addEventListener("click",requestPasswordReset);$("resetPasswordForm").addEventListener("submit",updateRecoveredPassword);$("authForm").addEventListener("submit",handleAuthSubmit);$("translatorTeamJoinForm")?.addEventListener("submit",joinTranslatorTeam);$("logoutBtn").addEventListener("click",()=>db?.auth.signOut());$("profileLogoutBtn").addEventListener("click",()=>db?.auth.signOut());$("searchInput").addEventListener("input",renderLibrary);$("membershipPlanSelect").addEventListener("change",e=>selectMembershipPlan(e.target.value));$("membershipRequestForm").addEventListener("submit",submitMembershipRequest);$("openCreateMangaBtn").addEventListener("click",()=>$("createMangaDialog").showModal());$("createMangaForm").addEventListener("submit",createManga);$("closeReaderBtn").addEventListener("click",closeReader);$("prevChapterBtn").addEventListener("click",()=>navigateReader(-1));$("nextChapterBtn").addEventListener("click",()=>navigateReader(1));$("readerTopBtn").addEventListener("click",()=>$("readerOverlay").scrollTo({top:0,behavior:"smooth"}));$("readerOverlay").addEventListener("scroll",trackReaderProgress,{passive:true});document.addEventListener("click",handleDocumentClick);document.querySelectorAll(".nav-link[data-view]").forEach(b=>b.addEventListener("click",()=>showView(b.dataset.view)));document.querySelectorAll("dialog").forEach(d=>d.addEventListener("click",e=>{if(e.target===d)d.close()}));document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!$("readerOverlay").classList.contains("hidden"))closeReader()})}
async function init(){document.body.classList.add("guest-mode");bindEvents();registerServiceWorker();configureAuthMode("login");if(!hasConfig){$("setupNotice").textContent="Системийг ажиллуулахын тулд config.js файлд Supabase URL болон anon key-г оруулна уу.";$("setupNotice").classList.remove("hidden");return}try{db=window.supabase.createClient(config.SUPABASE_URL,config.SUPABASE_ANON_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});db.auth.onAuthStateChange((event,session)=>setTimeout(()=>{if(event==="PASSWORD_RECOVERY")$("resetPasswordDialog").showModal();handleSession(session)},0));const{data,error}=await db.auth.getSession();if(error)throw error;await handleSession(data.session);if(location.hash.includes("type=recovery"))$("resetPasswordDialog").showModal()}catch(err){$("setupNotice").textContent=`Supabase холболтын алдаа: ${err.message}`;$("setupNotice").classList.remove("hidden")}}
init();
